import React from 'react';
import { Formik, Form, Field } from 'formik';
import * as Yup from 'yup';
import FormErrors from '../components/FormErrors';
import { useNavigate } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { clearCart } from '../redux/actions';

const Checkout = () => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const cart = useSelector((s) => s.cart || []);

  const initialValues = {
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    address: '',
    cardNumber: '',
  };

  const schema = Yup.object().shape({
    firstName: Yup.string()
      .required('First name is required')
      .max(30, 'First name must be at most 30 characters')
      .matches(/^[A-Za-z\-\s]+$/, 'First name must contain only letters, spaces or hyphens'),
    lastName: Yup.string()
      .required('Last name is required')
      .max(30, 'Last name must be at most 30 characters')
      .matches(/^[A-Za-z\-\s]+$/, 'Last name must contain only letters, spaces or hyphens'),
    email: Yup.string().email('Email is incorrect').required('Email is required'),
    phone: Yup.number()
      .typeError('Phone number must be numeric')
      .integer('Phone must be an integer')
      .positive('Phone must be positive')
      .required('Phone is required'),
    address: Yup.string().required('Address is required').min(10, 'Address is too short'),
    cardNumber: Yup.string()
      .required('Card number is required')
      .matches(/^[0-9]{16}$/, 'Card number must be 16 digits'),
  });

  const handleSubmit = (values, { setSubmitting }) => {
    setTimeout(() => {
      dispatch(clearCart());
      setSubmitting(false);
      navigate('/success', { state: { order: { items: cart, buyer: values } } });
    }, 500);
  };

  return (
    <section className="container checkout-page">
      <h2>Checkout</h2>
      <Formik initialValues={initialValues} validationSchema={schema} onSubmit={handleSubmit}>
        {({ errors, touched, isSubmitting }) => (
          <Form>
            <FormErrors errors={Object.keys(errors).length ? Object.fromEntries(Object.entries(errors).map(([k,v])=>[k,v])) : {}} />
            <div>
              <label>First Name</label>
              <Field name="firstName" />
            </div>
            <div>
              <label>Last Name</label>
              <Field name="lastName" />
            </div>
            <div>
              <label>Email</label>
              <Field name="email" type="email" />
            </div>
            <div>
              <label>Phone</label>
              <Field name="phone" type="tel" />
            </div>
            <div>
              <label>Address</label>
              <Field name="address" />
            </div>
            <div>
              <label>Card Number</label>
              <Field name="cardNumber" />
            </div>
            <div style={{ marginTop: 12 }}>
              <button type="submit" disabled={isSubmitting}>Place Order</button>
            </div>
          </Form>
        )}
      </Formik>
    </section>
  );
};

export default Checkout;
